-- Changelog-item: kortere, gegroepeerde zijbalk in het dossier.

insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-07','verbeterd','Dossiers','Een kortere zijbalk in de opdracht',
   'De tabbladen van een opdracht staan nu gegroepeerd onder vier koppen: Dossier, Voorbereiding, Uitvoering en Financieel. Zo hoef je niet meer langs een lange lijst te scrollen om bij Financieel te komen. VCA & Kwaliteit heet voortaan KAM/VGM en bundelt de kwaliteitscontrole, de oplevering en alle ingevulde formulieren; je wisselt daartussen met de knoppen bovenin het tabblad. Het klantportaal heeft geen eigen tabblad meer: op de Informatie-tab zie je in één oogopslag of het openstaat en wie er meekijkt, en achter "Instellingen" bepaal je wat de opdrachtgever te zien krijgt. Oude links naar deze tabbladen komen vanzelf op de nieuwe plek uit.');
